const fs = require('fs');
const crypto = require('crypto');

const backupDir = '/backups';

// 1. Buscar todos los archivos .dump en el volumen
let files = [];
try {
  files = fs.readdirSync(backupDir).filter(f => f.endsWith('.dump') && !f.startsWith('.'));
} catch (error) {
  return [{
    json: {
      isValid: false,
      status: "FAILED",
      error: `No se pudo acceder al directorio ${backupDir}: ${error.message}`,
      timestamp: new Date().toISOString()
    }
  }];
}

if (files.length === 0) {
  return [{
    json: {
      isValid: false,
      status: "FAILED",
      error: "No se encontraron archivos de backup (.dump) en el volumen.",
      timestamp: new Date().toISOString()
    }
  }];
}

// 2. Tomar el backup más reciente
const latestFile = files.sort().reverse()[0];
const fullPath = `${backupDir}/${latestFile}`;
const stats = fs.statSync(fullPath);
const sizeBytes = stats.size;
const sizeMB = (sizeBytes / (1024 * 1024)).toFixed(2);

// 3. Validar que no esté vacío (> 0 bytes)
if (sizeBytes <= 0) {
  return [{
    json: {
      isValid: false,
      status: "FAILED",
      filename: latestFile,
      sizeBytes: 0,
      error: "El archivo de backup existe pero está vacío (0 bytes).",
      timestamp: new Date().toISOString()
    }
  }];
}

// 4. Validar existencia del checksum .sha256
const shaFile = `${fullPath}.sha256`;
if (!fs.existsSync(shaFile)) {
  return [{
    json: {
      isValid: false,
      status: "FAILED",
      filename: latestFile,
      sizeBytes,
      sizeMB,
      error: `El archivo ${latestFile} no cuenta con su firma sha256 correspondiente.`,
      timestamp: new Date().toISOString()
    }
  }];
}

// 5. Comparar Checksum real contra el esperado
const shaFileContent = fs.readFileSync(shaFile, 'utf8').trim();
const expectedSha = shaFileContent.split(/\s+/)[0];

const fileBuffer = fs.readFileSync(fullPath);
const actualSha = crypto.createHash('sha256').update(fileBuffer).digest('hex');

const isChecksumMatch = (expectedSha.toLowerCase() === actualSha.toLowerCase());
//const isChecksumMatch = false;// Simulación forzada de fallo

if (!isChecksumMatch) {
  return [{
    json: {
      isValid: false,
      status: "CORRUPTED",
      filename: latestFile,
      sizeBytes,
      sizeMB,
      expectedSha,
      actualSha,
      error: "La firma SHA-256 no coincide. ¡El archivo de backup está corrupto!",
      timestamp: new Date().toISOString()
    }
  }];
}

// 6. Backup 100% íntegro y verificado
return [{
  json: {
    isValid: true,
    status: "SUCCESS",
    filename: latestFile,
    sizeBytes,
    sizeMB,
    checksum: actualSha,
    summary: `Backup verificado con éxito: ${latestFile} (${sizeMB} MB). Checksum SHA-256 íntegro.`,
    timestamp: new Date().toISOString()
  }
}];

